// Validate the booking payload, normalize every field, and precompute the
// lead time both policy gates read. Broken requests never reach the
// calendar: they are logged with the exact reason and answered 422.
// Phone accepts digits and the pack's masked demo format (+316****5678).
// Expected body fields: name, phone, email (optional), treatment,
// preferred_slot (ISO date-time), notes (optional).
const b = $input.first().json.body || $input.first().json;
const errors = [];
if (!b.name || String(b.name).trim().length < 2) errors.push('name too short');
if (!b.phone || !/^\+?[0-9* \-()]{8,20}$/.test(String(b.phone))) errors.push('phone invalid');
if (b.email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(String(b.email))) errors.push('email invalid');
if (!b.treatment) errors.push('treatment missing');
if (!b.preferred_slot || isNaN(new Date(b.preferred_slot).getTime())) errors.push('preferred_slot invalid');
else if (new Date(b.preferred_slot).getTime() < Date.now()) errors.push('preferred_slot in the past');

if (errors.length) {
  return [{ json: { ok: false, errors: errors, received_at: new Date().toISOString() } }];
}
const slot = new Date(b.preferred_slot);
const hoursUntil = (slot.getTime() - Date.now()) / 3600000;
return [{
  json: {
    ok: true,
    name: String(b.name).trim(),
    phone: String(b.phone).trim(),
    email: b.email ? String(b.email).trim().toLowerCase() : '',
    treatment: String(b.treatment).trim(),
    preferred_slot: slot.toISOString(),
    preferred_slot_local: slot.toLocaleString('en-GB', { weekday: 'long', day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit' }),
    hours_until: Math.round(hoursUntil),
    days_until: Math.round(hoursUntil / 24),
    notes: b.notes ? String(b.notes).slice(0, 500) : '',
    received_at: new Date().toISOString()
  }
}];

// Placeholder for the calendar/booking-system write.
// After import: replace with a Google Calendar 'Create Event' node (or your
// booking tool's API node). Keep the booking_status until the shop confirms.
const item = $input.first().json;
return [{
  json: {
    ...item,
    booking_status: 'pending_confirmation',
    calendar_event_id: 'DEMO-' + Date.now().toString(36).toUpperCase()
  }
}];

// Confirmation copy. Your send node (WhatsApp/SMS/email) goes after this.
const item = $input.first().json;
return [{
  json: {
    ...item,
    to: item.phone,
    channel: 'whatsapp',
    message: 'Thank you ' + item.name + '! We received your request for ' + item.treatment + ' on ' + item.preferred_slot_local + '. You will get a confirmation from us within 15 minutes.'
  }
}];

// Error path: invalid requests land here with every reason before the 422
// response leaves. In production, write to a 'booking_errors' sheet so a
// human can see which form fields keep failing and fix the form.
const items = $input.all();
return items.map((item) => ({
  json: {
    error: 'invalid booking request',
    errors: item.json.errors || [],
    name: item.json.name || null,
    treatment: item.json.treatment || null,
    logged_at: new Date().toISOString()
  }
}));

// Double-submit guard: the same phone number inside 30 minutes is a
// duplicate (double-clicked submit, retried POST). Fresh requests are
// remembered; duplicates are flagged and answered as if they succeeded,
// so the customer never sees an error for the same booking twice.
const staticData = $getWorkflowStaticData('global');
staticData.seen_phones = staticData.seen_phones || {};
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  const key = String(r.phone || '').replace(/[^0-9]/g, '');
  const last = staticData.seen_phones[key];
  const isDup = Boolean(last && Date.now() - last < 30 * 60 * 1000);
  if (!isDup) staticData.seen_phones[key] = Date.now();
  out.push({ json: { ...r, duplicate: isDup } });
}
return out;

// Duplicates end here with the same 200 shape as a fresh booking, but
// booking_status tells your dashboard this request was ignored on purpose,
// not booked twice.
const items = $input.all();
return items.map((item) => ({
  json: { ...item.json, booking_status: 'duplicate_ignored', handled_at: new Date().toISOString() }
}));

// Placeholder for your real send node (WhatsApp Business Cloud, SMS or
// email). The item already carries to, channel and message. After import:
// put your send node here and delete this one.
const items = $input.all();
return items.map((item) => ({
    json: { ...item.json, sent_at: new Date().toISOString(), transport: 'demo' }
}));
